def count_weekday_occurrences(year, month, weekday):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    t = [0,3,2,5,0,3,5,1,4,6,2,4]
    count = 0
    for day in range(1, lengths[month-1]+1):
        y = year
        m = month
        if m < 3:
            y -= 1
        w = (y + y//4 - y//100 + y//400 + t[m-1] + day) % 7
        if w == weekday:
            count += 1
    return count

